export const WAKE_EVENTS = [
  'timeout',
  'review_rejected',
  'council_opened',
  'council_split',
  'arbiter_decision',
  'urgent_alert'
];

export function parseCouncilComments(comments) {
  const results = [];
  for (const comment of comments) {
    const lines = comment.body.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      const match = trimmed.match(/^\[([a-z-]+)\](.*)$/);
      if (!match) continue;
      const marker = match[1];
      if (!MARKERS.includes(marker)) continue;
      const rest = match[2].trim();
      const fields = {};
      const pairs = rest.split(/\s+/);
      for (const pair of pairs) {
        const [key, ...valueParts] = pair.split('=');
        if (key && valueParts.length > 0) {
          fields[key] = valueParts.join('=');
        }
      }
      results.push({
        marker,
        fields,
        comment_id: comment.id,
        seat: fields.seat || null,
        round: fields.round ? parseInt(fields.round, 10) : null,
        raw: trimmed
      });
    }
  }
  return results;
}

export function evaluateCouncil({
  taskId,
  comments,
  requiredSeats = ['relay-claude', 'relay-gpt'],
  maxRounds = 2,
  reserved = false
}) {
  const parsed = parseCouncilComments(comments);

  const objections = parsed.filter(p => p.marker === 'objection');
  const proposals = parsed.filter(p => p.marker === 'proposal');
  const concurs = parsed.filter(p => p.marker === 'concur');
  const reviews = parsed.filter(p => p.marker === 'review');
  const councils = parsed.filter(p => p.marker === 'council');
  const consensuses = parsed.filter(p => p.marker === 'consensus');

  let blocking = 0;
  for (const obj of objections) {
    if (obj.fields.severity === 'blocking') {
      const objRound = obj.round || 0;
      const hasLaterProposal = proposals.some(p => (p.round || 0) >= objRound && p.comment_id > obj.comment_id);
      const hasConcur = concurs.some(c => c.fields.target_comment_id === String(obj.comment_id));
      if (!hasLaterProposal && !hasConcur) {
        blocking++;
      }
    }
  }

  if (blocking > 0) {
    return {
      stage: 'revision_required',
      round: Math.max(...parsed.map(p => p.round || 0), 0),
      consensus: false,
      blocking,
      next: 'revision_required',
      reason: 'blocking_objection'
    };
  }

  const seatReviews = {};
  for (const seat of requiredSeats) {
    seatReviews[seat] = reviews.filter(r => r.seat === seat);
  }

  const verdicts = {};
  for (const seat of requiredSeats) {
    const seatRev = seatReviews[seat];
    if (seatRev.length > 0) {
      verdicts[seat] = seatRev[seatRev.length - 1].fields.verdict;
    }
  }

  const maxCouncilRound = councils.length > 0 ? Math.max(...councils.map(c => c.round || 0)) : 0;
  const maxConsensusRound = consensuses.length > 0 ? Math.max(...consensuses.map(c => c.round || 0)) : 0;
  const currentRound = Math.max(maxCouncilRound, maxConsensusRound, 0);

  const verdictsArray = Object.values(verdicts);
  const hasPass = verdictsArray.includes('pass');
  const hasFail = verdictsArray.includes('fail');
  const allPass = verdictsArray.length === requiredSeats.length && verdictsArray.every(v => v === 'pass');

  if (reserved) {
    if (verdictsArray.length < requiredSeats.length) {
      return {
        stage: 'wait',
        round: currentRound,
        consensus: false,
        blocking,
        next: 'wait',
        reason: 'awaiting_required_reviews'
      };
    }
  }

  if (hasPass && hasFail) {
    if (currentRound >= maxRounds) {
      return {
        stage: 'council',
        round: currentRound,
        consensus: false,
        blocking,
        next: 'arbitrate',
        reason: 'max_rounds_reached'
      };
    }
    return {
      stage: 'council',
      round: currentRound,
      consensus: false,
      blocking,
      next: 'open_council',
      reason: 'verdict_mismatch'
    };
  }

  if (verdictsArray.length === 1 && !reserved) {
    if (currentRound >= maxRounds) {
      return {
        stage: 'council',
        round: currentRound,
        consensus: false,
        blocking,
        next: 'arbitrate',
        reason: 'max_rounds_reached'
      };
    }
    return {
      stage: 'council',
      round: currentRound,
      consensus: false,
      blocking,
      next: 'open_council',
      reason: 'single_review'
    };
  }

  const latestConsensus = consensuses.length > 0 ? consensuses[consensuses.length - 1] : null;
  if (latestConsensus && latestConsensus.fields.result === 'split' && currentRound >= maxRounds) {
    return {
      stage: 'council',
      round: currentRound,
      consensus: false,
      blocking,
      next: 'arbitrate',
      reason: 'consensus_split'
    };
  }

  if (allPass) {
    return {
      stage: 'approved',
      round: currentRound,
      consensus: true,
      blocking,
      next: 'approve',
      reason: 'all_pass'
    };
  }

  return {
    stage: 'wait',
    round: currentRound,
    consensus: allPass,
    blocking,
    next: 'wait',
    reason: 'awaiting_decision'
  };
}

export function wakeDecision({ taskId, event, sourceId, now, recent = [] }) {
  const dedupe_key = `${taskId}:${event}:${sourceId}`;

  if (recent.some(r => r.dedupe_key === dedupe_key)) {
    return {
      wake: false,
      reason: 'duplicate',
      dedupe_key,
      suppressed: true
    };
  }

  const oneHourAgo = now - 3600000;
  const taskRecent = recent.filter(r => r.taskId === taskId && r.timestamp > oneHourAgo);
  if (taskRecent.length >= 1) {
    return {
      wake: false,
      reason: 'task_rate_limited',
      dedupe_key,
      suppressed: true
    };
  }

  if (recent.length >= 6) {
    return {
      wake: false,
      reason: 'global_rate_limited',
      dedupe_key,
      suppressed: true
    };
  }

  return {
    wake: true,
    reason: 'wake',
    dedupe_key,
    suppressed: false
  };
}
